use super::*;

/// Which mode a resolved configuration IS in, or `None` when it matches neither.
///
/// Read from `provider` alone, deliberately. The model can legitimately differ from the packaged
/// default — a machine with a different local model installed, or a project pinned to a Claude tier —
/// and reporting such a project as "no mode" would be useless precisely where the answer matters.
pub fn mode_of(r: &Resolved) -> Option<&'static str> {
    match r.get("provider")? {
        "ollama" | "local" => Some("local"),
        "anthropic" => Some("claude"),
        _ => None,
    }
}
